<script>(()=>{const root=document.getElementById('options');document.getElementById('add-option').addEventListener('click',()=>{if(root.children.length>=10)return;const n=root.children.length+1;const row=document.createElement('div');row.className='input-group';row.innerHTML=`<span class="input-group-text">Opsi ${n}</span><input name="options[]" maxlength="255" class="form-control" required><button type="button" class="btn btn-outline-danger remove-option">Hapus</button>`;root.append(row);});root.addEventListener('click',e=>{if(e.target.classList.contains('remove-option')&&root.children.length>2)e.target.closest('.input-group').remove();});})();</script>
